import json, random

def get_user(r, db, user_id):
    key = f'user:{user_id}'
    cached = r.get(key)
    if cached is not None:
        return json.loads(cached)
    user = db.load_user(user_id)          # source of truth
    ttl = 300 + random.randint(0, 60)     # jitter against mass expiry
    r.set(key, json.dumps(user), ex=ttl)
    return user

def update_user(r, db, user_id, fields):
    db.save_user(user_id, fields)
    r.delete(f'user:{user_id}')           # invalidate, do not overwrite
